namespace fs=std::filesystem;
constexpr unsigned MAX_BONES=128;
constexpr float RUN_START=55.0f/24.0f, RUN_END=126.0f/24.0f, GOAL_START=126.0f/24.0f;
constexpr float CALL_START=174.0f/24.0f, CALL_END=234.0f/24.0f, SCENE_END=420.0f/24.0f;

static std::string readFile(const fs::path& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("No pude abrir "+p.string());std::ostringstream s;s<<f.rdbuf();return s.str();}
static std::string low(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return char(std::tolower(c));});return s;}
static glm::mat4 cv(const aiMatrix4x4& m){return glm::mat4(m.a1,m.b1,m.c1,m.d1,m.a2,m.b2,m.c2,m.d2,m.a3,m.b3,m.c3,m.d3,m.a4,m.b4,m.c4,m.d4);}
static glm::vec3 cv(const aiVector3D& v){return {v.x,v.y,v.z};}
static glm::quat cv(const aiQuaternion& q){return {q.w,q.x,q.y,q.z};}

class Shader{
public:
 GLuint id=0;
 Shader(const fs::path& vp,const fs::path& fp){GLuint v=compile(GL_VERTEX_SHADER,readFile(vp),vp.string()),f=compile(GL_FRAGMENT_SHADER,readFile(fp),fp.string());id=glCreateProgram();glAttachShader(id,v);glAttachShader(id,f);glLinkProgram(id);GLint ok=0;glGetProgramiv(id,GL_LINK_STATUS,&ok);if(!ok)throw std::runtime_error("No se pudieron enlazar los shaders");glDeleteShader(v);glDeleteShader(f);}
 ~Shader(){if(id)glDeleteProgram(id);} void use()const{glUseProgram(id);} GLint loc(const char* n)const{return glGetUniformLocation(id,n);}
 void set(const char* n,int x)const{glUniform1i(loc(n),x);} void set(const char* n,float x)const{glUniform1f(loc(n),x);} void set(const char* n,const glm::vec3& x)const{glUniform3fv(loc(n),1,glm::value_ptr(x));} void set(const char* n,const glm::mat4& x)const{glUniformMatrix4fv(loc(n),1,GL_FALSE,glm::value_ptr(x));}
private:
 static GLuint compile(GLenum type,const std::string& src,const std::string& name){GLuint s=glCreateShader(type);const char* p=src.c_str();glShaderSource(s,1,&p,nullptr);glCompileShader(s);GLint ok=0;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){GLint n=0;glGetShaderiv(s,GL_INFO_LOG_LENGTH,&n);std::string log(std::max(n,1),0);glGetShaderInfoLog(s,n,nullptr,log.data());throw std::runtime_error("Shader "+name+": "+log);}return s;}
};

struct Vertex{glm::vec3 pos{0},normal{0,1,0};glm::vec2 uv{0};glm::ivec4 ids{-1};glm::vec4 weights{0};};
struct Bone{unsigned id=0;glm::mat4 offset{1};};
struct Material{glm::vec3 color{0.8f};float alpha=1;GLuint texture=0;};
struct Mesh{GLuint vao=0,vbo=0,ebo=0;GLsizei count=0;Material material;bool skinned=false;};
struct Node{const aiNode* src=nullptr;std::string actor;std::vector<unsigned> meshIds;std::vector<Node> children;};
struct Clip{const aiAnimation* anim=nullptr;double time=0;std::string actor;};

class Scene{
public:
 Assimp::Importer importer;const aiScene* data=nullptr;Node root;glm::mat4 invRoot{1};std::vector<Mesh> meshes;std::vector<Material> materials;std::unordered_map<std::string,Bone> bones;std::vector<glm::mat4> finalBones;std::unordered_map<std::string,const aiAnimation*> anims;std::unordered_map<std::string,GLuint> textureCache;std::unordered_map<std::string,unsigned> meshCache;
 explicit Scene(const fs::path& p){data=importer.ReadFile(p.string(),aiProcess_Triangulate|aiProcess_GenSmoothNormals|aiProcess_JoinIdenticalVertices|aiProcess_LimitBoneWeights|aiProcess_SortByPType|aiProcess_ValidateDataStructure);if(!data||!data->mRootNode)throw std::runtime_error(std::string("Assimp: ")+importer.GetErrorString());invRoot=glm::inverse(cv(data->mRootNode->mTransformation));for(unsigned i=0;i<data->mNumAnimations;++i)anims[data->mAnimations[i]->mName.C_Str()]=data->mAnimations[i];loadMaterials();root=build(data->mRootNode,"");finalBones.assign(bones.size(),glm::mat4(1));std::cout<<"GLB: "<<data->mNumMeshes<<" mallas, "<<anims.size()<<" animaciones, "<<bones.size()<<" huesos\n";}
 static double duration(const aiAnimation* a){return a->mDuration/(a->mTicksPerSecond>0?a->mTicksPerSecond:24.0);}
 void draw(const Shader& s,float t){finalBones.assign(bones.size(),glm::mat4(1));auto clips=clipsAt(t);updateBones(root,glm::mat4(1),clips);drawNode(root,glm::mat4(1),clips,s);}
 void drawDepth(const Shader& s,float t){finalBones.assign(bones.size(),glm::mat4(1));auto clips=clipsAt(t);updateBones(root,glm::mat4(1),clips);drawDepthNode(root,glm::mat4(1),clips,s);}
private:
 void loadMaterials(){materials.resize(data->mNumMaterials);stbi_set_flip_vertically_on_load(true);for(unsigned i=0;i<data->mNumMaterials;++i){const aiMaterial* m=data->mMaterials[i];auto& out=materials[i];aiColor4D c;if(aiGetMaterialColor(m,AI_MATKEY_COLOR_DIFFUSE,&c)==AI_SUCCESS){out.color={c.r,c.g,c.b};out.alpha=c.a;}aiString p;if(m->GetTexture(aiTextureType_BASE_COLOR,0,&p)!=AI_SUCCESS)m->GetTexture(aiTextureType_DIFFUSE,0,&p);if(p.length)out.texture=texture(p.C_Str());}}
 GLuint texture(const std::string& path){auto it=textureCache.find(path);if(it!=textureCache.end())return it->second;int w=0,h=0,n=0;unsigned char* pix=nullptr;bool stbiOwned=true;const aiTexture* e=data->GetEmbeddedTexture(path.c_str());if(e&&e->mHeight==0)pix=stbi_load_from_memory(reinterpret_cast<const stbi_uc*>(e->pcData),int(e->mWidth),&w,&h,&n,0);else if(e){stbiOwned=false;w=int(e->mWidth);h=int(e->mHeight);n=4;pix=new unsigned char[size_t(w)*size_t(h)*4];for(int i=0;i<w*h;++i){pix[i*4]=e->pcData[i].r;pix[i*4+1]=e->pcData[i].g;pix[i*4+2]=e->pcData[i].b;pix[i*4+3]=e->pcData[i].a;}}if(!pix)return 0;GLuint id=0;glGenTextures(1,&id);glBindTexture(GL_TEXTURE_2D,id);GLenum fmt=n==4?GL_RGBA:GL_RGB;glTexImage2D(GL_TEXTURE_2D,0,n==4?GL_SRGB8_ALPHA8:GL_SRGB8,w,h,0,fmt,GL_UNSIGNED_BYTE,pix);glGenerateMipmap(GL_TEXTURE_2D);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);if(stbiOwned)stbi_image_free(pix);else delete[] pix;textureCache[path]=id;return id;}
 Node build(const aiNode* src,const std::string& inherited){Node n;n.src=src;n.actor=inherited;std::string name=low(src->mName.C_Str());if(name.find("jugador chicharito rig")!=std::string::npos||name.find("control | jugador carrera")!=std::string::npos)n.actor="player";if(name.find("arbitro rig")!=std::string::npos||name.find("control | árbitro")!=std::string::npos)n.actor="referee";for(unsigned i=0;i<src->mNumMeshes;++i){unsigned ix=src->mMeshes[i];std::string key=std::to_string(ix)+"|"+n.actor;auto it=meshCache.find(key);if(it==meshCache.end()){meshCache[key]=makeMesh(ix,n.actor);n.meshIds.push_back(meshCache[key]);}else n.meshIds.push_back(it->second);}for(unsigned i=0;i<src->mNumChildren;++i)n.children.push_back(build(src->mChildren[i],n.actor));return n;}
 unsigned makeMesh(unsigned ix,const std::string& actor){const aiMesh* m=data->mMeshes[ix];std::vector<Vertex> v(m->mNumVertices);std::vector<unsigned> indices;for(unsigned i=0;i<m->mNumVertices;++i){v[i].pos=cv(m->mVertices[i]);if(m->HasNormals())v[i].normal=cv(m->mNormals[i]);if(m->HasTextureCoords(0))v[i].uv={m->mTextureCoords[0][i].x,m->mTextureCoords[0][i].y};}for(unsigned f=0;f<m->mNumFaces;++f)for(unsigned k=0;k<m->mFaces[f].mNumIndices;++k)indices.push_back(m->mFaces[f].mIndices[k]);bool skin=false;for(unsigned b=0;b<m->mNumBones;++b){const aiBone* bone=m->mBones[b];std::string key=actor+"|"+bone->mName.C_Str();unsigned id;auto it=bones.find(key);if(it==bones.end()){if(bones.size()>=MAX_BONES)continue;id=unsigned(bones.size());bones.emplace(key,Bone{id,cv(bone->mOffsetMatrix)});}else id=it->second.id;for(unsigned j=0;j<bone->mNumWeights;++j){auto w=bone->mWeights[j];auto& vert=v[w.mVertexId];for(int slot=0;slot<4;++slot)if(vert.ids[slot]<0){vert.ids[slot]=int(id);vert.weights[slot]=w.mWeight;break;}}skin=true;}
  Mesh g;g.count=GLsizei(indices.size());g.skinned=skin;if(m->mMaterialIndex<materials.size())g.material=materials[m->mMaterialIndex];glGenVertexArrays(1,&g.vao);glGenBuffers(1,&g.vbo);glGenBuffers(1,&g.ebo);glBindVertexArray(g.vao);glBindBuffer(GL_ARRAY_BUFFER,g.vbo);glBufferData(GL_ARRAY_BUFFER,v.size()*sizeof(Vertex),v.data(),GL_STATIC_DRAW);glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,g.ebo);glBufferData(GL_ELEMENT_ARRAY_BUFFER,indices.size()*sizeof(unsigned),indices.data(),GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,pos));glEnableVertexAttribArray(1);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,normal));glEnableVertexAttribArray(2);glVertexAttribPointer(2,2,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,uv));glEnableVertexAttribArray(3);glVertexAttribIPointer(3,4,GL_INT,sizeof(Vertex),(void*)offsetof(Vertex,ids));glEnableVertexAttribArray(4);glVertexAttribPointer(4,4,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,weights));glBindVertexArray(0);meshes.push_back(g);return unsigned(meshes.size()-1);}
 std::vector<Clip> clipsAt(float t)const{std::vector<Clip> c;auto add=[&](const std::string& name,double local,const std::string& actor=""){auto it=anims.find(name);if(it!=anims.end())c.push_back({it->second,std::clamp(local,0.0,duration(it->second)),actor});};add("Control | jugador carreraAction.003",t,"player");add("Control | autobúsAction",t);for(auto& a:anims)if(low(a.first).rfind("plane",0)==0)add(a.first,t);auto run=anims.find("Jugador CHICHARITO Carrera.004");if(run!=anims.end()&&t>=RUN_START&&t<=RUN_END){double d=duration(run->second);add(run->first,std::fmod(t-RUN_START,d),"player");}auto call=anims.find("Arbitro Señal de falta.004");if(call!=anims.end()&&t>=CALL_START&&t<=CALL_END)add(call->first,(t-CALL_START)/(CALL_END-CALL_START)*duration(call->second),"referee");for(const char* name:{"Arbitro mano izquierdoAction.004","Arbitro antebrazo izquierdoAction.004","Arbitro brazo izquierdoAction.004","Arbitro silbatoAction.004"}){auto it=anims.find(name);if(it!=anims.end()&&t>=CALL_START&&t<=CALL_END)add(name,(t-CALL_START)/(CALL_END-CALL_START)*duration(it->second),"referee");}if(t>=GOAL_START)add("Balon_GolAction.005",t-GOAL_START);float cs=245.f/24.f;if(t>=cs)for(auto& a:anims)if(low(a.first).find("cart")!=std::string::npos)add(a.first,t-cs);return c;}
 const aiNodeAnim* channel(const Clip& c,const std::string& node,const std::string& actor)const{if(!c.actor.empty()&&c.actor!=actor)return nullptr;std::string name=low(c.anim->mName.C_Str());if(actor=="player"&&name.find("arbitro")!=std::string::npos)return nullptr;if(actor=="referee"&&name.find("jugador")!=std::string::npos)return nullptr;for(unsigned i=0;i<c.anim->mNumChannels;++i)if(node==c.anim->mChannels[i]->mNodeName.C_Str())return c.anim->mChannels[i];return nullptr;}
 template<class Key,class V,class F>static V sample(const Key* keys,unsigned count,double t,V fallback,F convert){if(!count)return fallback;if(count==1||t<=keys[0].mTime)return convert(keys[0].mValue);if(t>=keys[count-1].mTime)return convert(keys[count-1].mValue);unsigned i=0;while(i+1<count&&keys[i+1].mTime<t)++i;double span=keys[i+1].mTime-keys[i].mTime;float f=span>0?float((t-keys[i].mTime)/span):0;return glm::mix(convert(keys[i].mValue),convert(keys[i+1].mValue),f);}
 glm::mat4 local(const Node& n,const std::vector<Clip>& clips)const{aiVector3D p,s;aiQuaternion r;n.src->mTransformation.Decompose(s,r,p);glm::vec3 pos=cv(p),scale=cv(s);glm::quat rot=cv(r);for(const auto& c:clips){const aiNodeAnim* ch=channel(c,n.src->mName.C_Str(),n.actor);if(!ch)continue;double tick=c.time*(c.anim->mTicksPerSecond>0?c.anim->mTicksPerSecond:24.0);pos=sample(ch->mPositionKeys,ch->mNumPositionKeys,tick,pos,[](const aiVector3D& x){return cv(x);});scale=sample(ch->mScalingKeys,ch->mNumScalingKeys,tick,scale,[](const aiVector3D& x){return cv(x);});if(ch->mNumRotationKeys){unsigned i=0;while(i+1<ch->mNumRotationKeys&&ch->mRotationKeys[i+1].mTime<tick)++i;aiQuaternion q;if(ch->mNumRotationKeys==1||tick<=ch->mRotationKeys[0].mTime)q=ch->mRotationKeys[0].mValue;else if(tick>=ch->mRotationKeys[ch->mNumRotationKeys-1].mTime)q=ch->mRotationKeys[ch->mNumRotationKeys-1].mValue;else{double span=ch->mRotationKeys[i+1].mTime-ch->mRotationKeys[i].mTime;aiQuaternion::Interpolate(q,ch->mRotationKeys[i].mValue,ch->mRotationKeys[i+1].mValue,span>0?float((tick-ch->mRotationKeys[i].mTime)/span):0);q.Normalize();}rot=cv(q);}}return glm::translate(glm::mat4(1),pos)*glm::mat4_cast(rot)*glm::scale(glm::mat4(1),scale);}
 void updateBones(const Node& n,const glm::mat4& parent,const std::vector<Clip>& clips){glm::mat4 global=parent*local(n,clips);auto bi=bones.find(n.actor+"|"+n.src->mName.C_Str());if(bi!=bones.end())finalBones[bi->second.id]=invRoot*global*bi->second.offset;for(const auto& c:n.children)updateBones(c,global,clips);}
 void drawDepthNode(const Node& n,const glm::mat4& parent,const std::vector<Clip>& clips,const Shader& s){glm::mat4 global=parent*local(n,clips);for(unsigned id:n.meshIds){const Mesh& m=meshes[id];s.set("uModel",global);s.set("uHasBones",m.skinned?1:0);if(m.skinned){std::vector<glm::mat4> safe(MAX_BONES,glm::mat4(1));std::copy(finalBones.begin(),finalBones.end(),safe.begin());glUniformMatrix4fv(s.loc("uBones[0]"),MAX_BONES,GL_FALSE,glm::value_ptr(safe[0]));}glBindVertexArray(m.vao);glDrawElements(GL_TRIANGLES,m.count,GL_UNSIGNED_INT,nullptr);}for(const auto& c:n.children)drawDepthNode(c,global,clips,s);}
 void drawNode(const Node& n,const glm::mat4& parent,const std::vector<Clip>& clips,const Shader& s){glm::mat4 global=parent*local(n,clips);for(unsigned id:n.meshIds){const Mesh& m=meshes[id];s.set("uModel",global);s.set("uHasBones",m.skinned?1:0);s.set("uMaterial.color",m.material.color);s.set("uMaterial.alpha",m.material.alpha);s.set("uHasTexture",m.material.texture?1:0);s.set("uTexture",0);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,m.material.texture);if(m.skinned){std::vector<glm::mat4> safe(MAX_BONES,glm::mat4(1));std::copy(finalBones.begin(),finalBones.end(),safe.begin());glUniformMatrix4fv(s.loc("uBones[0]"),MAX_BONES,GL_FALSE,glm::value_ptr(safe[0]));}glBindVertexArray(m.vao);glDrawElements(GL_TRIANGLES,m.count,GL_UNSIGNED_INT,nullptr);}for(const auto& c:n.children)drawNode(c,global,clips,s);}
};

struct Camera{glm::vec3 pos{-46,1.8f,8},front{-1,0,0},up{0,1,0},right{0,0,1};float yaw=180,pitch=-2,fov=55;void vectors(){glm::vec3 f{std::cos(glm::radians(yaw))*std::cos(glm::radians(pitch)),std::sin(glm::radians(pitch)),std::sin(glm::radians(yaw))*std::cos(glm::radians(pitch))};front=glm::normalize(f);right=glm::normalize(glm::cross(front,glm::vec3(0,1,0)));up=glm::normalize(glm::cross(right,front));}glm::mat4 view()const{return glm::lookAt(pos,pos+front,up);}};
enum class Mode{FirstPerson,Broadcast};
struct App{Camera cam;Mode mode=Mode::Broadcast;bool firstMouse=true,playing=false,night=false,lights=true;float lastX=0,lastY=0,time=0,radius=28;double previous=0;int home=0,away=0;};
static glm::vec3 playerAt(float t){float f=std::clamp((t-RUN_START)/(RUN_END-RUN_START),0.f,1.f);return {-46.f-18.f*f,0,8.f};}
static void mouse(GLFWwindow* w,double x,double y){auto*a=static_cast<App*>(glfwGetWindowUserPointer(w));if(!a)return;if(a->firstMouse){a->lastX=float(x);a->lastY=float(y);a->firstMouse=false;}float dx=float(x)-a->lastX,dy=a->lastY-float(y);a->lastX=float(x);a->lastY=float(y);a->cam.yaw+=dx*.1f;a->cam.pitch=std::clamp(a->cam.pitch+dy*.1f,-75.f,75.f);a->cam.vectors();}
static void scroll(GLFWwindow*w,double,double y){auto*a=static_cast<App*>(glfwGetWindowUserPointer(w));if(a)a->cam.fov=std::clamp(a->cam.fov-float(y)*2,30.f,75.f);}
static void key(GLFWwindow*w,int k,int,int act,int){if(act!=GLFW_PRESS)return;auto*a=static_cast<App*>(glfwGetWindowUserPointer(w));if(!a)return;if(k==GLFW_KEY_ESCAPE)glfwSetWindowShouldClose(w,1);if(k==GLFW_KEY_SPACE)a->playing=!a->playing;if(k==GLFW_KEY_R){a->time=0;a->playing=false;}if(k==GLFW_KEY_G){a->time=GOAL_START;a->playing=true;}if(k==GLFW_KEY_F){a->time=CALL_START;a->playing=true;}if(k==GLFW_KEY_L)a->lights=!a->lights;if(k==GLFW_KEY_N)a->night=!a->night;if(k==GLFW_KEY_1)a->mode=Mode::FirstPerson;if(k==GLFW_KEY_2)a->mode=Mode::Broadcast;if(k==GLFW_KEY_J)++a->home;if(k==GLFW_KEY_K)++a->away;if(k==GLFW_KEY_BACKSPACE)a->home=a->away=0;}
static void move(App&a,GLFWwindow*w,float dt){float speed=18*dt;glm::vec3 f=a.cam.front;f.y=0;f=glm::normalize(f);glm::vec3 r=glm::normalize(glm::cross(f,glm::vec3(0,1,0)));if(a.mode==Mode::FirstPerson){if(glfwGetKey(w,GLFW_KEY_W)==GLFW_PRESS)a.cam.pos+=f*speed;if(glfwGetKey(w,GLFW_KEY_S)==GLFW_PRESS)a.cam.pos-=f*speed;if(glfwGetKey(w,GLFW_KEY_A)==GLFW_PRESS)a.cam.pos-=r*speed;if(glfwGetKey(w,GLFW_KEY_D)==GLFW_PRESS)a.cam.pos+=r*speed;}else{if(glfwGetKey(w,GLFW_KEY_W)==GLFW_PRESS)a.radius=std::max(9.f,a.radius-speed);if(glfwGetKey(w,GLFW_KEY_S)==GLFW_PRESS)a.radius=std::min(85.f,a.radius+speed);if(glfwGetKey(w,GLFW_KEY_A)==GLFW_PRESS)a.cam.yaw-=35*dt;if(glfwGetKey(w,GLFW_KEY_D)==GLFW_PRESS)a.cam.yaw+=35*dt;a.cam.pitch=std::clamp(a.cam.pitch,8.f,52.f);a.cam.vectors();}}

static void rect(std::vector<float>& v,float x,float y,float w,float h){v.insert(v.end(),{x,y,x+w,y,x+w,y-h,x,y,x+w,y-h,x,y-h});}
static const std::array<std::string,7>& glyph(char c){static const std::map<char,std::array<std::string,7>> g={
 {'0',{"01110","10001","10011","10101","11001","10001","01110"}},{'1',{"00100","01100","00100","00100","00100","00100","01110"}},{'2',{"01110","10001","00001","00010","00100","01000","11111"}},{'3',{"11110","00001","00001","01110","00001","00001","11110"}},{'4',{"00010","00110","01010","10010","11111","00010","00010"}},{'5',{"11111","10000","10000","11110","00001","00001","11110"}},{'6',{"01110","10000","10000","11110","10001","10001","01110"}},{'7',{"11111","00001","00010","00100","01000","01000","01000"}},{'8',{"01110","10001","10001","01110","10001","10001","01110"}},{'9',{"01110","10001","10001","01111","00001","00001","01110"}},{'M',{"10001","11011","10101","10101","10001","10001","10001"}},{'A',{"01110","10001","10001","11111","10001","10001","10001"}},{'R',{"11110","10001","10001","11110","10100","10010","10001"}},{'C',{"01111","10000","10000","10000","10000","10000","01111"}},{'D',{"11110","10001","10001","10001","10001","10001","11110"}},{'O',{"01110","10001","10001","10001","10001","10001","01110"}},{':',{"00000","00100","00100","00000","00100","00100","00000"}},{' ',{"00000","00000","00000","00000","00000","00000","00000"}}};auto it=g.find(c);return it==g.end()?g.at(' '):it->second;}
static void text(Shader& s,GLuint vao,GLuint vbo,const std::string& t,float x,float y,float p,glm::vec3 color){std::vector<float> v;float cur=x;for(char c:t){auto& g=glyph(c);for(int r=0;r<7;++r)for(int col=0;col<5;++col)if(g[r][col]=='1')rect(v,cur+col*p,y-r*p,p*.82f,p*.82f);cur+=p*6;}glBindBuffer(GL_ARRAY_BUFFER,vbo);glBufferData(GL_ARRAY_BUFFER,v.size()*sizeof(float),v.data(),GL_DYNAMIC_DRAW);glBindVertexArray(vao);s.use();s.set("uColor",color);glDrawArrays(GL_TRIANGLES,0,GLsizei(v.size()/2));}

